"""Columns shared by every table. Mix into a model: `class Posting(UUIDPrimaryKeyMixin, ..., Base)`.

A mixin is a plain class (not a Base subclass); SQLAlchemy copies its `mapped_column`s into
each model that inherits it. TypeORM parallel: an abstract base entity that entities extend.
How column declarations read: see docs/database.md → Models.
"""

import uuid
from datetime import datetime

from sqlalchemy import DateTime, func
from sqlalchemy.orm import Mapped, mapped_column


class UUIDPrimaryKeyMixin:
    """`id`: UUID primary key generated by Postgres (`gen_random_uuid()`), first column."""

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True, server_default=func.gen_random_uuid(), sort_order=-10
    )


class TimestampMixin:
    """`created_at` / `updated_at` as `timestamptz`, set by Postgres, last columns.

    `eager_defaults=True` fetches DB-generated values with RETURNING on UPDATE too.
    Without it, `updated_at` is expired after an UPDATE, and reading it would need a lazy
    SELECT, which async SQLAlchemy forbids (`MissingGreenlet`).
    """

    __mapper_args__ = {"eager_defaults": True}

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), sort_order=10
    )

    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        onupdate=func.now(),
        server_default=func.now(),
        sort_order=10,
    )
